    claim_id BIGINT NOT NULL REFERENCES claim (id),
    status VARCHAR(20) NOT NULL,
    changed_by VARCHAR(255) NOT NULL,
    changed_on DATE NOT NULL,
    due VARCHAR(32) NOT NULL
);
